arguments.command:
cd /workspace && python3 - <<'EOF'
import sys
sys.path.insert(0,'deps')
import zstandard as zstd
c=zstd.ZstdCompressor(); d=bytearray(c.compress(b'hello world'))
print('orig flag',hex(d[4]))
d2=bytearray(d); d2[4]|=0x10
try:
 p=zstd.get_frame_parameters(d2)
 print('params ok',p)
except Exception as e: print('params err',type(e),e)
try:
 out=zstd.ZstdDecompressor().decompress(bytes(d2))
 print('decomp ok',out)
except Exception as e: print('decomp err',type(e),e)
# reserved bit set
d3=bytearray(d);d3[4]|=0x08
try: print('reserved params',zstd.get_frame_parameters(d3))
except Exception as e: print('reserved err',type(e),e)
EOF
